1	// Phase 1: the hero scroll animation. Phase 2: the headline with the closed book. Phase 3: aayat on the open pages.
2	// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
3	// Spec: WEBSITE-BUILD.md sections 2 to 4; the settings the user chose are under section 7.
4	
5	(() => {
6	  const clamp = (v) => Math.min(1, Math.max(0, v));
7	  const smoothstep = (t) => t * t * (3 - 2 * t);
8	
9	  // Frames --------------------------------------------------------------------
10	
11	  const SKIP = [39, 40]; // identical to f038, a hold in the source video
12	  const urls = [];
13	  for (let i = 0; i <= 88; i++) {
14	    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
15	  }
16	  const LAST = urls.length - 1; // 87 frames, indices 0..86
17	
18	  // Geometry, in pixels of the 1280x720 frames ----------------------------------
19	
20	  const SRC_W = 1280;
21	  const SRC_H = 720;
22	  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
23	  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
24	  const SPINE = 640;       // right edge until the cover passes upright
25	  const OPEN_RIGHT = 1037; // right edge fully open
26	  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
27	  const FEATHER_Y = 40;
28	
29	  // Timeline, in screen heights of scrolling on a computer -----------------------
30	  // Phones scroll two thirds as far for everything (the hero is shorter there, in styles.css).
31	
32	  const REST = 0.45;  // closed book with the headline
33	  const OPEN = 2.25;  // the cover opens (the same scrolling as when the user signed off phase 1)
34	  const SETTLE = 0.4; // open, blank pages
35	  const AYAH = 1;     // one group of aayat fades in over the first FADE of this, then stays
36	  const FADE = 0.3;
37	  const TOTAL = REST + OPEN + SETTLE + AYAH; // 4.1; .hero in styles.css is one screen taller than this
38	  const NAME_GONE = 8; // the headline has faded out by this frame, early in the opening
39	
40	  // Smoothing ---------------------------------------------------------------------
41	
42	  // A mouse wheel scrolls in steps, so everything glides toward the scroll position instead of
43	  // jumping to it, and the book cross-fades between frames. The user chose this "slow glide" by eye.
44	  const GLIDE = 0.28; // roughly the seconds it takes to close two thirds of the gap
45	
46	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
47	  const hero = document.querySelector('.hero');
48	  const stage = hero.querySelector('.stage');
49	  const canvas = stage.querySelector('canvas');
50	  const wordmark = stage.querySelector('.wordmark');
51	  const ctx = canvas.getContext('2d');
52	
53	  const frames = []; // decoded images by index, filled in as they arrive
54	  const rights = []; // measured right edge of the book in each frame
55	  const started = new Set();
56	  const groups = []; // one element per group of aayat, filled in when aayat.json arrives
57	
58	  let scale = 1;      // footage pixels to CSS pixels, set on resize
59	  let pos = null;     // scroll position shown, in screens; lags the real one while gliding
60	  let painted = null; // position last shown
61	  let drawn = null;   // frame last drawn; fractional between frames
62	  let last = 0;       // time of the previous glide step, 0 when at rest
63	  let dirty = true;
64	  let queued = false;
65	  let visible = true;
66	  let current = -1;   // the group of aayat on the pages, -1 while they are blank
67	  let previous = -1;  // the last group shown, so the next pass shows a different one
68	
69	  // Loading -----------------------------------------------------------------------
70	
71	  function load(i) {
72	    if (started.has(i)) return;
73	    started.add(i);
74	    const img = new Image();
75	    img.src = urls[i];
76	    img.decode().then(
77	      () => {
78	        frames[i] = img;
79	        rights[i] = measureRight(img);
80	        if (i >= LAST - 3) place(); // the open book's measured edge sets where the pages are
81	        dirty = true;
82	        schedule();
83	      },
84	      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
85	    );
86	  }
87	
88	  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
89	  function loadAll() {
90	    load(0);
91	    load(LAST);
92	    for (const step of [8, 4, 2, 1]) {
93	      for (let i = 0; i <= LAST; i += step) load(i);
94	    }
95	  }
96	
97	  // Once the cover passes upright its cream lining faces the camera, so the book's right
98	  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
99	  const probe = document.createElement('canvas');
100	  probe.width = SRC_W;
101	  probe.height = 1;
102	  const probeCtx = probe.getContext('2d', { willReadFrequently: true });
103	
104	  function measureRight(img) {
105	    try {
106	      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
107	      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
108	      for (let x = SRC_W - 1; x > SPINE; x--) {
109	        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
110	      }
111	      return SPINE;
112	    } catch {
113	      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
114	    }
115	  }
116	
117	  // Averaged over nearby frames so the centring glides instead of stepping.
118	  function rightEdge(i) {
119	    let sum = 0;
120	    let n = 0;
121	    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
122	      if (rights[j] != null) {
123	        sum += rights[j];
124	        n++;
125	      }
126	    }
127	    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
128	  }
129	
130	  // Aayat -------------------------------------------------------------------------
131	  // The exact text comes from aayat.json, written by fetch-aayat.js from Quran.com. Never typed by hand.
132	
133	  const aayat = document.createElement('div');
134	  aayat.className = 'aayat';
135	  stage.append(aayat);
136	
137	  function el(tag, className, text) {
138	    const node = document.createElement(tag);
139	    node.className = className;
140	    if (text) node.textContent = text;
141	    return node;
142	  }
143	
144	  // Arabic on the right page, the first page in a mushaf, each ayah closed by its numbered marker.
145	  // The left page carries the surah name, reference and English meaning.
146	  function renderGroup({ ref, surah, aayat: verses }) {
147	    const group = el('section', 'group');
148	    const right = el('div', 'page right');
149	    const arabic = el('p', 'arabic');
150	    arabic.lang = 'ar';
151	    arabic.dir = 'rtl';
152	    for (const { key, text } of verses) {
153	      const marker = el('span', 'marker', `۝${Number(key.split(':')[1]).toLocaleString('ar-u-nu-arab')}`);
154	      marker.setAttribute('aria-hidden', 'true');
155	      arabic.append(`${text} `, marker, ' ');
156	    }
157	    right.append(arabic);
158	    const left = el('div', 'page left');
159	    left.append(
160	      el('p', 'surah', surah),
161	      el('p', 'meaning', verses.map((v) => v.translation).join(' ')),
162	      el('p', 'ref', ref.replace('-', '–')),
163	    );
164	    group.append(right, left);
165	    return group;
166	  }
167	
168	  fetch('aayat.json')
169	    .then((res) => res.json())
170	    .then((data) => {
171	      for (const g of data.groups) groups.push(aayat.appendChild(renderGroup(g)));
172	      fit();
173	      dirty = true;
174	      schedule();
175	    })
176	    .catch(() => console.warn('No aayat yet: run fetch-aayat.js'));
177	
178	  // Where the open book's pages are: CSS lays the text over them from these.
179	  function place() {
180	    const open = (BOOK_LEFT + rightEdge(LAST)) / 2;
181	    stage.style.setProperty('--s', scale);
182	    stage.style.setProperty('--x0', `${canvas.clientWidth / 2 - open * scale}px`);
183	    stage.style.setProperty('--y0', `${(canvas.clientHeight - SRC_H * scale) / 2}px`);
184	    stage.style.setProperty('--book-h', `${BOOK_H * scale}px`);
185	  }
186	
187	  // Shrinks a page's text until it fits, for aayat longer than the page holds at its normal size.
188	  function fit() {
189	    for (const page of aayat.querySelectorAll('.page')) {
190	      page.style.fontSize = '';
191	      let size = parseFloat(getComputedStyle(page).fontSize);
192	      while (page.scrollHeight > page.clientHeight && size > 10) {
193	        size *= 0.94;
194	        page.style.fontSize = `${size}px`;
195	      }
196	    }
197	  }
198	
199	  // One group at a time, picked at random each time the pages come into view. It fades in once the
200	  // book has settled open and stays; scrolling back up to blank pages lets the next pass pick again.
201	  // Under reduced motion a random group is simply shown.
202	  function showAayat(s, still) {
203	    const fade = still ? 1 : smoothstep(clamp((s - REST - OPEN - SETTLE) / FADE));
204	    if (fade === 0) current = -1;
205	    else if (current < 0 && groups.length) current = pick();
206	    groups.forEach((group, k) => {
207	      group.style.opacity = k === current ? fade : 0;
208	    });
209	  }
210	
211	  // A random group, never the one shown last time.
212	  function pick() {
213	    let k;
214	    do k = Math.floor(Math.random() * groups.length);
215	    while (groups.length > 1 && k === previous);
216	    return (previous = k);
217	  }
218	
219	  // Drawing -----------------------------------------------------------------------
220	
221	  // Cross-fades the two frames either side of a position, or while they are still loading, draws
222	  // the nearest frame that has arrived. Returns false while no frame has loaded yet.
223	  function draw(at) {
224	    const a = Math.floor(at);
225	    const b = Math.min(a + 1, LAST);
226	    const f = at - a;
227	    const fade = f > 0 && !!frames[a] && !!frames[b];
228	    const base = fade ? a : nearestLoaded(Math.round(at));
229	    if (base < 0) return false;
230	
231	    const width = canvas.clientWidth;
232	    const height = canvas.clientHeight;
233	    // The book is centred by choosing which part of the frame is drawn, never by moving the canvas.
234	    const centre = (BOOK_LEFT + rightEdge(a) + (rightEdge(b) - rightEdge(a)) * f) / 2;
235	    const w = SRC_W * scale;
236	    const h = SRC_H * scale;
237	    const x = width / 2 - centre * scale;
238	    const y = (height - h) / 2;
239	
240	    ctx.globalCompositeOperation = 'source-over';
241	    ctx.clearRect(0, 0, width, height);
242	    ctx.drawImage(frames[base], x, y, w, h);
243	    if (fade) {
244	      ctx.globalAlpha = f;
245	      ctx.drawImage(frames[b], x, y, w, h);
246	      ctx.globalAlpha = 1;
247	    }
248	
249	    // Fade the frame's rectangle out at its edges so it never shows against the stage.
250	    ctx.globalCompositeOperation = 'destination-in';
251	    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
252	    ctx.fillRect(x, y, w, h);
253	    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
254	    ctx.fillRect(x, y, w, h);
255	    ctx.globalCompositeOperation = 'source-over';
256	    return true;
257	  }
258	
259	  function feather(gradient, edge) {
260	    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
261	    gradient.addColorStop(edge, '#000');
262	    gradient.addColorStop(1 - edge, '#000');
263	    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
264	    return gradient;
265	  }
266	
267	  // How far the hero has been scrolled, in computer screen heights (0 to TOTAL).
268	  function targetScroll() {
269	    const range = hero.offsetHeight - stage.offsetHeight;
270	    return range > 0 ? clamp(-hero.getBoundingClientRect().top / range) * TOTAL : 0;
271	  }
272	
273	  // The book's frame at a scroll position; smoothstep eases into and out of the opening.
274	  function frameAt(s) {
275	    return smoothstep(clamp((s - REST) / OPEN)) * LAST;
276	  }
277	
278	  function nearestLoaded(i) {
279	    for (let d = 0; d <= LAST; d++) {
280	      if (frames[i - d]) return i - d;
281	      if (frames[i + d]) return i + d;
282	    }
283	    return -1;
284	  }
285	
286	  function schedule() {
287	    if (queued) return;
288	    queued = true;
289	    requestAnimationFrame(step);
290	  }
291	
292	  // Each animation frame, moves part of the way toward the scroll position and keeps going until it
293	  // arrives. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
294	  function step(now) {
295	    queued = false;
296	    if (!visible) {
297	      last = 0;
298	      return;
299	    }
300	    const target = targetScroll();
301	    if (pos === null || reduceMotion.matches) {
302	      pos = target;
303	    } else {
304	      const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
305	      pos += (target - pos) * (1 - Math.exp(-dt / GLIDE));
306	      if (Math.abs(target - pos) < 0.0005) pos = target;
307	    }
308	    last = pos === target ? 0 : now;
309	    paint();
310	    if (pos !== target) schedule();
311	  }
312	
313	  // Updates the headline and aayat, and redraws the book only when its frame, the size or the loaded
314	  // frames have changed. Under reduced motion the book is shown open and the headline stays.
315	  function paint() {
316	    if (pos === null || (pos === painted && !dirty)) return;
317	    const still = reduceMotion.matches;
318	    const frame = still ? LAST : frameAt(pos);
319	    wordmark.style.opacity = still ? 1 : 1 - clamp(frame / NAME_GONE);
320	    showAayat(pos, still);
321	    painted = pos;
322	    if (frame !== drawn || dirty) {
323	      if (draw(frame)) {
324	        drawn = frame;
325	        dirty = false;
326	      }
327	    }
328	  }
329	
330	  function resize() {
331	    const width = canvas.clientWidth;
332	    const height = canvas.clientHeight;
333	    const dpr = Math.min(devicePixelRatio || 1, 2);
334	    canvas.width = Math.round(width * dpr);
335	    canvas.height = Math.round(height * dpr);
336	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
337	    ctx.imageSmoothingQuality = 'high';
338	    // One size for the whole opening: the open book always fits, and the 720p footage is
339	    // never stretched past its own size.
340	    scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
341	    place();
342	    fit();
343	    dirty = true;
344	    paint(); // draw now: resizing the canvas has just cleared it
345	    schedule(); // the hero's height follows the window, so the scroll position may now mean a different frame
346	  }
347	
348	  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
349	  function applyMotion() {
350	    document.documentElement.classList.toggle('still', reduceMotion.matches);
351	    if (reduceMotion.matches) load(LAST);
352	    else loadAll();
353	    dirty = true;
354	    schedule();
355	  }
356	
357	  // TRYOUT --------------------------------------------------------------------------
358	  // Phase 3 options, shown only on this PC or a phone on the same wifi. Each choice sets a data
359	  // attribute on <html> that styles.css reads. Once the user picks: move the picks into styles.css,
360	  // then delete this block, the TRYOUT part of styles.css and the unused Arabic font in index.html.
361	
362	  if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
363	    const OPTIONS = {
364	      arabic: ['Arabic lettering', { 'Amiri Quran': 'amiri', Scheherazade: 'scheherazade' }],
365	      left: ['Left page', { 'Surah name': 'name', 'English meaning': 'meaning' }],
366	    };
367	    const panel = document.createElement('details');
368	    panel.className = 'tryout';
369	    panel.open = true;
370	    panel.innerHTML = '<summary>Options</summary>';
371	    for (const [key, [label, choices]] of Object.entries(OPTIONS)) {
372	      const row = document.createElement('div');
373	      row.append(el('span', '', label));
374	      for (const [text, value] of Object.entries(choices)) {
375	        const b = el('button', '', text);
376	        b.type = 'button';
377	        b.addEventListener('click', () => {
378	          document.documentElement.dataset[key] = value;
379	          for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
380	          fit();
381	        });
382	        row.append(b);
383	      }
384	      row.querySelector('button').click(); // the first choice matches the defaults in styles.css
385	      panel.append(row);
386	    }
387	    document.body.append(panel);
388	  }
389	
390	  addEventListener('scroll', schedule, { passive: true });
391	  document.fonts.addEventListener('loadingdone', fit); // text changes size when its font arrives
392	  reduceMotion.addEventListener('change', applyMotion);
393	  new ResizeObserver(resize).observe(canvas);
394	  new IntersectionObserver(([entry]) => {
395	    visible = entry.isIntersecting;
396	    dirty = true;
397	    schedule();
398	  }).observe(hero);
399	  applyMotion();
400	})();
401

