// Phase 4: atmosphere. Dust drifting in the light in front of the book, and a slight movement of the book
// (with its aayat) while nobody is scrolling. Spec: WEBSITE-BUILD.md sections 5 and 7.
// All of it is decoration: it stops offscreen and under reduced motion, and "Auto" quality steps it down
// on devices that measurably can't keep up.

(() => {
  const TAU = Math.PI * 2;
  const wave = (t, period, phase = 0) => Math.sin((t / period) * TAU + phase);
  const ease = (value, target, seconds, dt) => value + (target - value) * (1 - Math.exp(-dt / seconds));

  const hero = document.querySelector('.hero');
  const stage = hero.querySelector('.stage');
  const subject = stage.querySelector('.subject');
  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const mouse = matchMedia('(hover: hover) and (pointer: fine)');

  // Starting choices, until the user picks from the options panel.
  const settings = { dust: 'few', idle: 'float', strength: 'subtle', follow: 'dust', quality: 'auto' };

  // Dust
  const DENSITY = { few: 26000, more: 13000 }; // one mote per this many square CSS pixels of screen
  const MAX_MOTES = 140;
  const PARALLAX = 24; // CSS px the nearest motes shift with the mouse at the screen's edge

  // Book movement
  const STRENGTH = { subtle: 1, more: 2.2 };
  const IDLE_DELAY = 300; // ms after the last scroll before the book starts moving again
  const TILT = 2;         // degrees the book turns toward the mouse at the screen's edge

  // Sine waves whose periods never line up, so the movement doesn't visibly repeat. k is 0 while
  // scrolling and eases up to the chosen strength once the page is still.
  const IDLE = {
    float: (t, k) => `translate3d(${wave(t, 11) * 1.5 * k * unit}px, ${wave(t, 6.5) * 4 * k * unit}px, 0)`,
    breathe: (t, k) => `scale(${1 + (wave(t, 7) + 1) * 0.005 * k})`,
    drift: (t, k) =>
      `rotateX(${wave(t, 9) * 0.6 * k}deg) rotateY(${wave(t, 13, 1) * k}deg) translate3d(0, ${wave(t, 7) * 2 * k * unit}px, 0)`,
  };

  // Quality: "Auto" watches the frame rate only while the page is still (while scrolling, the book's
  // frames cost more than the atmosphere does) and steps down full -> lite -> off when frames keep
  // arriving late.
  const SLOW_FRAME = 24;  // ms; a frame later than this means one was dropped on a 60 Hz screen
  const BAD_SHARE = 0.25; // a second is bad when a quarter of its frames were late
  const BAD_SECONDS = 3;  // bad seconds in a row before stepping down
  const WARMUP = 4000;    // ms after load before judging, while the book's frames are still decoding

  const canvas = document.createElement('canvas');
  canvas.className = 'dust';
  canvas.setAttribute('aria-hidden', 'true');
  stage.append(canvas);
  const ctx = canvas.getContext('2d');

  const pointer = { x: 0, y: 0 }; // the mouse, -1 to 1 from the middle of the screen
  const look = { x: 0, y: 0 };    // follows the pointer with a lag

  let width = 0;
  let height = 0;
  let unit = 1;               // screen height / 900, so movement looks the same size on a phone and a computer
  let motes = [];
  let presence = 0;           // fades the dust in when it (re)starts
  let idle = 0;               // 0 while scrolling, 1 once still
  let motion = settings.idle; // the last movement chosen, so switching it off eases out
  let level = 'full';         // full, lite or off
  let reason = '';
  let visible = true;
  let raf = 0;
  let last = 0;
  let lastScroll = -Infinity;
  let scrolled = false;       // scrolled during the current second, so that second isn't judged
  let windowStart = 0;
  let frames = 0;
  let late = 0;
  let badSeconds = 0;
  let fps = 0;
  let readout = null;         // the options panel's status line, on this PC only

  // Soft dots drawn once, then stamped, so each frame is only image copies.
  function sprite(size, core) {
    const c = document.createElement('canvas');
    c.width = c.height = size;
    const g = c.getContext('2d');
    const r = size / 2;
    const glow = g.createRadialGradient(r, r, 0, r, r, r);
    glow.addColorStop(0, 'rgba(255, 240, 210, 1)');
    glow.addColorStop(core, 'rgba(240, 210, 150, 0.5)');
    glow.addColorStop(1, 'rgba(212, 175, 55, 0)');
    g.fillStyle = glow;
    g.fillRect(0, 0, size, size);
    return c;
  }
  const SPECK = sprite(32, 0.3); // a fleck of dust in the light
  const BLUR = sprite(64, 0.55); // one close to the camera, out of focus

  // Dust ----------------------------------------------------------------------------------

  // A mote at height y, anywhere across. At full quality one in ten is close to the camera: large, faint, blurred.
  function spawn(y) {
    const near = level === 'full' && Math.random() < 0.1;
    const depth = near ? 0.85 + Math.random() * 0.15 : 0.15 + Math.random() * 0.6;
    return {
      x: Math.random() * width,
      y,
      depth,
      sprite: near ? BLUR : SPECK,
      r: near ? 6 + Math.random() * 8 : 1.2 + depth * 2.4,
      rise: (2 + depth * 8) * unit,       // CSS px a second; nearer motes move faster
      sway: (3 + Math.random() * 9) * unit,
      wander: 8 + Math.random() * 10,     // seconds per side-to-side drift
      twinkle: 3 + Math.random() * 5,     // seconds per brightening
      phase: Math.random() * TAU,
      alpha: near ? 0.04 + Math.random() * 0.05 : 0.2 + depth * 0.5,
    };
  }

  function populate() {
    const per = DENSITY[settings.dust];
    let n = per ? Math.min(MAX_MOTES, Math.round((width * height) / per)) : 0;
    if (level === 'lite') n = Math.round(n / 2);
    motes = [];
    for (let i = 0; i < n; i++) motes.push(spawn(Math.random() * height));
    presence = 0;
    ctx.clearRect(0, 0, width, height);
  }

  function drawDust(t, dt) {
    if (!motes.length) return;
    ctx.clearRect(0, 0, width, height);
    presence = ease(presence, 1, 0.8, dt);
    const dx = -look.x * PARALLAX * unit;
    const dy = -look.y * PARALLAX * unit;
    for (const m of motes) {
      m.y -= m.rise * dt;
      if (m.y < -m.r) Object.assign(m, spawn(height + m.r));
      const x = m.x + wave(t, m.wander, m.phase) * m.sway + dx * m.depth;
      const y = m.y + dy * m.depth;
      ctx.globalAlpha = m.alpha * presence * (0.7 + 0.3 * wave(t, m.twinkle, m.phase));
      ctx.drawImage(m.sprite, x - m.r, y - m.r, m.r * 2, m.r * 2);
    }
    ctx.globalAlpha = 1;
  }

  // The book --------------------------------------------------------------------------------

  // Only transform changes, so the browser moves the already-drawn book without redrawing it.
  function moveBook(t) {
    const k = idle * STRENGTH[settings.strength];
    const tilt = settings.follow === 'book' && level === 'full';
    let transform = tilt || motion === 'drift' ? 'perspective(1600px) ' : '';
    if (tilt) transform += `rotateX(${-look.y * TILT * 0.6}deg) rotateY(${look.x * TILT}deg) `;
    if (k > 0.001) transform += IDLE[motion](t, k);
    subject.style.transform = transform;
  }

  // Quality -----------------------------------------------------------------------------------

  function measure(now, dtMs) {
    if (!windowStart) windowStart = now;
    frames++;
    if (dtMs > SLOW_FRAME) late++;
    if (now - windowStart < 1000) return;
    fps = Math.round((frames * 1000) / (now - windowStart));
    if (settings.quality === 'auto' && !scrolled && now > WARMUP) {
      badSeconds = late / frames > BAD_SHARE ? badSeconds + 1 : 0;
      if (badSeconds >= BAD_SECONDS) setLevel(level === 'full' ? 'lite' : 'off', 'frames kept arriving late');
    }
    windowStart = now;
    frames = late = 0;
    scrolled = false;
    report();
  }

  function setLevel(next, why = '') {
    level = next;
    reason = why;
    badSeconds = 0;
    resize(); // the number of motes and the canvas sharpness depend on the level
    refresh();
  }

  // One plain line for the options panel: what is running, how smoothly, and on what device.
  function report() {
    if (!readout) return;
    const cores = navigator.hardwareConcurrency;
    const memory = navigator.deviceMemory; // Chrome, Edge and Opera only
    const device = [cores && `${cores} cores`, memory && `${memory} GB memory`].filter(Boolean).join(', ');
    let state;
    if (level === 'off') state = `Atmosphere off${reason ? ` (${reason})` : ''}`;
    else if (!running()) state = 'Paused';
    else state = `${level === 'full' ? 'Full' : 'Lite'} quality, ${fps ? `${fps} frames a second` : 'measuring…'}`;
    readout.textContent = `${state}${settings.quality === 'auto' ? ' · auto' : ''}${device ? ` · this device: ${device}` : ''}`;
  }

  // Loop --------------------------------------------------------------------------------------

  function resize() {
    width = canvas.clientWidth;
    height = canvas.clientHeight;
    unit = height / 900;
    const dpr = Math.min(devicePixelRatio || 1, level === 'full' ? 1.5 : 1); // soft dots don't need full retina sharpness
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    populate();
  }

  function running() {
    return (
      visible &&
      !reduceMotion.matches &&
      level !== 'off' &&
      (settings.dust !== 'off' || settings.idle !== 'off' || settings.follow !== 'off')
    );
  }

  // Starts the loop if there is anything to animate; otherwise leaves the book still and the dust cleared.
  function refresh() {
    const on = running();
    if (on) wake();
    else {
      subject.style.transform = '';
      ctx.clearRect(0, 0, width, height);
    }
    subject.style.willChange = on && (settings.idle !== 'off' || settings.follow === 'book') ? 'transform' : '';
    report();
  }

  function wake() {
    if (raf) return;
    last = 0;
    windowStart = 0;
    frames = late = 0;
    raf = requestAnimationFrame(frame);
  }

  // Uses elapsed time, so it moves at the same speed on 60 Hz and 144 Hz screens.
  function frame(now) {
    raf = 0;
    if (!running()) return refresh();
    const dtMs = last ? now - last : 1000 / 60;
    const dt = Math.min(dtMs, 50) / 1000;
    last = now;
    const t = now / 1000;
    const quiet = now - lastScroll > IDLE_DELAY;
    idle = ease(idle, quiet && settings.idle !== 'off' ? 1 : 0, quiet ? 1.2 : 0.2, dt);
    const following = settings.follow !== 'off' && mouse.matches;
    look.x = ease(look.x, following ? pointer.x : 0, 0.6, dt);
    look.y = ease(look.y, following ? pointer.y : 0, 0.6, dt);
    moveBook(t);
    drawDust(t, dt);
    measure(now, dtMs);
    if (!raf && running()) raf = requestAnimationFrame(frame);
  }

  addEventListener(
    'scroll',
    () => {
      lastScroll = performance.now();
      scrolled = true;
    },
    { passive: true },
  );
  addEventListener(
    'pointermove',
    (e) => {
      if (e.pointerType !== 'mouse') return;
      pointer.x = (e.clientX / innerWidth) * 2 - 1;
      pointer.y = (e.clientY / innerHeight) * 2 - 1;
    },
    { passive: true },
  );
  document.documentElement.addEventListener('mouseleave', () => {
    pointer.x = 0;
    pointer.y = 0;
  });
  reduceMotion.addEventListener('change', refresh);
  new ResizeObserver(resize).observe(canvas);
  new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting;
    refresh();
  }).observe(hero);

  // TRYOUT ------------------------------------------------------------------------------------
  // Phase 4 options, added to main.js's panel on this PC or a phone on the same wifi. Once the user
  // picks: put the picks in `settings` above, then delete this block and the .readout CSS.

  const panel = /^(localhost|[\d.]+)$/.test(location.hostname) && document.querySelector('.tryout');
  if (panel) {
    const OPTIONS = {
      dust: ['Dust', { Off: 'off', Few: 'few', More: 'more' }],
      idle: ['Book when still', { Off: 'off', Float: 'float', Breathe: 'breathe', Drift: 'drift' }],
      strength: ['Movement size', { Subtle: 'subtle', More: 'more' }],
      follow: ['Follow the mouse', { Off: 'off', Dust: 'dust', 'Dust and book': 'book' }],
      quality: ['Quality', { Auto: 'auto', Full: 'full', Lite: 'lite' }],
    };
    for (const [key, [label, choices]] of Object.entries(OPTIONS)) {
      if (key === 'follow' && !mouse.matches) continue; // phones have no mouse
      const row = document.createElement('div');
      const name = document.createElement('span');
      name.textContent = label;
      row.append(name);
      for (const [text, value] of Object.entries(choices)) {
        const b = document.createElement('button');
        b.type = 'button';
        b.textContent = text;
        b.setAttribute('aria-pressed', settings[key] === value);
        b.addEventListener('click', () => {
          settings[key] = value;
          for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
          if (key === 'idle' && value !== 'off') motion = value;
          if (key === 'quality') {
            setLevel(value === 'lite' ? 'lite' : 'full');
            return;
          }
          if (key === 'dust') populate();
          refresh();
        });
        row.append(b);
      }
      panel.append(row);
    }
    readout = document.createElement('p');
    readout.className = 'readout';
    panel.append(readout);
    report();
  }
})();

toolUseResult.content:
// Phase 4: atmosphere. Dust drifting in the light in front of the book, and a slight movement of the book
// (with its aayat) while nobody is scrolling. Spec: WEBSITE-BUILD.md sections 5 and 7.
// All of it is decoration: it stops offscreen and under reduced motion, and "Auto" quality steps it down
// on devices that measurably can't keep up.

(() => {
  const TAU = Math.PI * 2;
  const wave = (t, period, phase = 0) => Math.sin((t / period) * TAU + phase);
  const ease = (value, target, seconds, dt) => value + (target - value) * (1 - Math.exp(-dt / seconds));

  const hero = document.querySelector('.hero');
  const stage = hero.querySelector('.stage');
  const subject = stage.querySelector('.subject');
  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const mouse = matchMedia('(hover: hover) and (pointer: fine)');

  // Starting choices, until the user picks from the options panel.
  const settings = { dust: 'few', idle: 'float', strength: 'subtle', follow: 'dust', quality: 'auto' };

  // Dust
  const DENSITY = { few: 26000, more: 13000 }; // one mote per this many square CSS pixels of screen
  const MAX_MOTES = 140;
  const PARALLAX = 24; // CSS px the nearest motes shift with the mouse at the screen's edge

  // Book movement
  const STRENGTH = { subtle: 1, more: 2.2 };
  const IDLE_DELAY = 300; // ms after the last scroll before the book starts moving again
  const TILT = 2;         // degrees the book turns toward the mouse at the screen's edge

  // Sine waves whose periods never line up, so the movement doesn't visibly repeat. k is 0 while
  // scrolling and eases up to the chosen strength once the page is still.
  const IDLE = {
    float: (t, k) => `translate3d(${wave(t, 11) * 1.5 * k * unit}px, ${wave(t, 6.5) * 4 * k * unit}px, 0)`,
    breathe: (t, k) => `scale(${1 + (wave(t, 7) + 1) * 0.005 * k})`,
    drift: (t, k) =>
      `rotateX(${wave(t, 9) * 0.6 * k}deg) rotateY(${wave(t, 13, 1) * k}deg) translate3d(0, ${wave(t, 7) * 2 * k * unit}px, 0)`,
  };

  // Quality: "Auto" watches the frame rate only while the page is still (while scrolling, the book's
  // frames cost more than the atmosphere does) and steps down full -> lite -> off when frames keep
  // arriving late.
  const SLOW_FRAME = 24;  // ms; a frame later than this means one was dropped on a 60 Hz screen
  const BAD_SHARE = 0.25; // a second is bad when a quarter of its frames were late
  const BAD_SECONDS = 3;  // bad seconds in a row before stepping down
  const WARMUP = 4000;    // ms after load before judging, while the book's frames are still decoding

  const canvas = document.createElement('canvas');
  canvas.className = 'dust';
  canvas.setAttribute('aria-hidden', 'true');
  stage.append(canvas);
  const ctx = canvas.getContext('2d');

  const pointer = { x: 0, y: 0 }; // the mouse, -1 to 1 from the middle of the screen
  const look = { x: 0, y: 0 };    // follows the pointer with a lag

  let width = 0;
  let height = 0;
  let unit = 1;               // screen height / 900, so movement looks the same size on a phone and a computer
  let motes = [];
  let presence = 0;           // fades the dust in when it (re)starts
  let idle = 0;               // 0 while scrolling, 1 once still
  let motion = settings.idle; // the last movement chosen, so switching it off eases out
  let level = 'full';         // full, lite or off
  let reason = '';
  let visible = true;
  let raf = 0;
  let last = 0;
  let lastScroll = -Infinity;
  let scrolled = false;       // scrolled during the current second, so that second isn't judged
  let windowStart = 0;
  let frames = 0;
  let late = 0;
  let badSeconds = 0;
  let fps = 0;
  let readout = null;         // the options panel's status line, on this PC only

  // Soft dots drawn once, then stamped, so each frame is only image copies.
  function sprite(size, core) {
    const c = document.createElement('canvas');
    c.width = c.height = size;
    const g = c.getContext('2d');
    const r = size / 2;
    const glow = g.createRadialGradient(r, r, 0, r, r, r);
    glow.addColorStop(0, 'rgba(255, 240, 210, 1)');
    glow.addColorStop(core, 'rgba(240, 210, 150, 0.5)');
    glow.addColorStop(1, 'rgba(212, 175, 55, 0)');
    g.fillStyle = glow;
    g.fillRect(0, 0, size, size);
    return c;
  }
  const SPECK = sprite(32, 0.3); // a fleck of dust in the light
  const BLUR = sprite(64, 0.55); // one close to the camera, out of focus

  // Dust ----------------------------------------------------------------------------------

  // A mote at height y, anywhere across. At full quality one in ten is close to the camera: large, faint, blurred.
  function spawn(y) {
    const near = level === 'full' && Math.random() < 0.1;
    const depth = near ? 0.85 + Math.random() * 0.15 : 0.15 + Math.random() * 0.6;
    return {
      x: Math.random() * width,
      y,
      depth,
      sprite: near ? BLUR : SPECK,
      r: near ? 6 + Math.random() * 8 : 1.2 + depth * 2.4,
      rise: (2 + depth * 8) * unit,       // CSS px a second; nearer motes move faster
      sway: (3 + Math.random() * 9) * unit,
      wander: 8 + Math.random() * 10,     // seconds per side-to-side drift
      twinkle: 3 + Math.random() * 5,     // seconds per brightening
      phase: Math.random() * TAU,
      alpha: near ? 0.04 + Math.random() * 0.05 : 0.2 + depth * 0.5,
    };
  }

  function populate() {
    const per = DENSITY[settings.dust];
    let n = per ? Math.min(MAX_MOTES, Math.round((width * height) / per)) : 0;
    if (level === 'lite') n = Math.round(n / 2);
    motes = [];
    for (let i = 0; i < n; i++) motes.push(spawn(Math.random() * height));
    presence = 0;
    ctx.clearRect(0, 0, width, height);
  }

  function drawDust(t, dt) {
    if (!motes.length) return;
    ctx.clearRect(0, 0, width, height);
    presence = ease(presence, 1, 0.8, dt);
    const dx = -look.x * PARALLAX * unit;
    const dy = -look.y * PARALLAX * unit;
    for (const m of motes) {
      m.y -= m.rise * dt;
      if (m.y < -m.r) Object.assign(m, spawn(height + m.r));
      const x = m.x + wave(t, m.wander, m.phase) * m.sway + dx * m.depth;
      const y = m.y + dy * m.depth;
      ctx.globalAlpha = m.alpha * presence * (0.7 + 0.3 * wave(t, m.twinkle, m.phase));
      ctx.drawImage(m.sprite, x - m.r, y - m.r, m.r * 2, m.r * 2);
    }
    ctx.globalAlpha = 1;
  }

  // The book --------------------------------------------------------------------------------

  // Only transform changes, so the browser moves the already-drawn book without redrawing it.
  function moveBook(t) {
    const k = idle * STRENGTH[settings.strength];
    const tilt = settings.follow === 'book' && level === 'full';
    let transform = tilt || motion === 'drift' ? 'perspective(1600px) ' : '';
    if (tilt) transform += `rotateX(${-look.y * TILT * 0.6}deg) rotateY(${look.x * TILT}deg) `;
    if (k > 0.001) transform += IDLE[motion](t, k);
    subject.style.transform = transform;
  }

  // Quality -----------------------------------------------------------------------------------

  function measure(now, dtMs) {
    if (!windowStart) windowStart = now;
    frames++;
    if (dtMs > SLOW_FRAME) late++;
    if (now - windowStart < 1000) return;
    fps = Math.round((frames * 1000) / (now - windowStart));
    if (settings.quality === 'auto' && !scrolled && now > WARMUP) {
      badSeconds = late / frames > BAD_SHARE ? badSeconds + 1 : 0;
      if (badSeconds >= BAD_SECONDS) setLevel(level === 'full' ? 'lite' : 'off', 'frames kept arriving late');
    }
    windowStart = now;
    frames = late = 0;
    scrolled = false;
    report();
  }

  function setLevel(next, why = '') {
    level = next;
    reason = why;
    badSeconds = 0;
    resize(); // the number of motes and the canvas sharpness depend on the level
    refresh();
  }

  // One plain line for the options panel: what is running, how smoothly, and on what device.
  function report() {
    if (!readout) return;
    const cores = navigator.hardwareConcurrency;
    const memory = navigator.deviceMemory; // Chrome, Edge and Opera only
    const device = [cores && `${cores} cores`, memory && `${memory} GB memory`].filter(Boolean).join(', ');
    let state;
    if (level === 'off') state = `Atmosphere off${reason ? ` (${reason})` : ''}`;
    else if (!running()) state = 'Paused';
    else state = `${level === 'full' ? 'Full' : 'Lite'} quality, ${fps ? `${fps} frames a second` : 'measuring…'}`;
    readout.textContent = `${state}${settings.quality === 'auto' ? ' · auto' : ''}${device ? ` · this device: ${device}` : ''}`;
  }

  // Loop --------------------------------------------------------------------------------------

  function resize() {
    width = canvas.clientWidth;
    height = canvas.clientHeight;
    unit = height / 900;
    const dpr = Math.min(devicePixelRatio || 1, level === 'full' ? 1.5 : 1); // soft dots don't need full retina sharpness
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    populate();
  }

  function running() {
    return (
      visible &&
      !reduceMotion.matches &&
      level !== 'off' &&
      (settings.dust !== 'off' || settings.idle !== 'off' || settings.follow !== 'off')
    );
  }

  // Starts the loop if there is anything to animate; otherwise leaves the book still and the dust cleared.
  function refresh() {
    const on = running();
    if (on) wake();
    else {
      subject.style.transform = '';
      ctx.clearRect(0, 0, width, height);
    }
    subject.style.willChange = on && (settings.idle !== 'off' || settings.follow === 'book') ? 'transform' : '';
    report();
  }

  function wake() {
    if (raf) return;
    last = 0;
    windowStart = 0;
    frames = late = 0;
    raf = requestAnimationFrame(frame);
  }

  // Uses elapsed time, so it moves at the same speed on 60 Hz and 144 Hz screens.
  function frame(now) {
    raf = 0;
    if (!running()) return refresh();
    const dtMs = last ? now - last : 1000 / 60;
    const dt = Math.min(dtMs, 50) / 1000;
    last = now;
    const t = now / 1000;
    const quiet = now - lastScroll > IDLE_DELAY;
    idle = ease(idle, quiet && settings.idle !== 'off' ? 1 : 0, quiet ? 1.2 : 0.2, dt);
    const following = settings.follow !== 'off' && mouse.matches;
    look.x = ease(look.x, following ? pointer.x : 0, 0.6, dt);
    look.y = ease(look.y, following ? pointer.y : 0, 0.6, dt);
    moveBook(t);
    drawDust(t, dt);
    measure(now, dtMs);
    if (!raf && running()) raf = requestAnimationFrame(frame);
  }

  addEventListener(
    'scroll',
    () => {
      lastScroll = performance.now();
      scrolled = true;
    },
    { passive: true },
  );
  addEventListener(
    'pointermove',
    (e) => {
      if (e.pointerType !== 'mouse') return;
      pointer.x = (e.clientX / innerWidth) * 2 - 1;
      pointer.y = (e.clientY / innerHeight) * 2 - 1;
    },
    { passive: true },
  );
  document.documentElement.addEventListener('mouseleave', () => {
    pointer.x = 0;
    pointer.y = 0;
  });
  reduceMotion.addEventListener('change', refresh);
  new ResizeObserver(resize).observe(canvas);
  new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting;
    refresh();
  }).observe(hero);

  // TRYOUT ------------------------------------------------------------------------------------
  // Phase 4 options, added to main.js's panel on this PC or a phone on the same wifi. Once the user
  // picks: put the picks in `settings` above, then delete this block and the .readout CSS.

  const panel = /^(localhost|[\d.]+)$/.test(location.hostname) && document.querySelector('.tryout');
  if (panel) {
    const OPTIONS = {
      dust: ['Dust', { Off: 'off', Few: 'few', More: 'more' }],
      idle: ['Book when still', { Off: 'off', Float: 'float', Breathe: 'breathe', Drift: 'drift' }],
      strength: ['Movement size', { Subtle: 'subtle', More: 'more' }],
      follow: ['Follow the mouse', { Off: 'off', Dust: 'dust', 'Dust and book': 'book' }],
      quality: ['Quality', { Auto: 'auto', Full: 'full', Lite: 'lite' }],
    };
    for (const [key, [label, choices]] of Object.entries(OPTIONS)) {
      if (key === 'follow' && !mouse.matches) continue; // phones have no mouse
      const row = document.createElement('div');
      const name = document.createElement('span');
      name.textContent = label;
      row.append(name);
      for (const [text, value] of Object.entries(choices)) {
        const b = document.createElement('button');
        b.type = 'button';
        b.textContent = text;
        b.setAttribute('aria-pressed', settings[key] === value);
        b.addEventListener('click', () => {
          settings[key] = value;
          for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
          if (key === 'idle' && value !== 'off') motion = value;
          if (key === 'quality') {
            setLevel(value === 'lite' ? 'lite' : 'full');
            return;
          }
          if (key === 'dust') populate();
          refresh();
        });
        row.append(b);
      }
      panel.append(row);
    }
    readout = document.createElement('p');
    readout.className = 'readout';
    panel.append(readout);
    report();
  }
})();

