// TRYOUT --------------------------------------------------------------------------
// Phase 3 options, shown only on this PC or a phone on the same wifi. Each choice sets a data
// attribute on <html> that styles.css reads. Once the user picks: move the picks into styles.css,
// then delete this block, the TRYOUT part of styles.css and the unused Arabic font in index.html.

if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
  const OPTIONS = {
    arabic: ['Arabic lettering', { 'Amiri Quran': 'amiri', Scheherazade: 'scheherazade' }],
    left: ['Left page', { 'Surah name': 'name', 'English meaning': 'meaning' }],
  };
  const panel = document.createElement('details');
  panel.className = 'tryout';
  panel.open = true;
  panel.innerHTML = '<summary>Options</summary>';
  for (const [key, [label, choices]] of Object.entries(OPTIONS)) {
    const row = document.createElement('div');
    row.append(el('span', '', label));
    for (const [text, value] of Object.entries(choices)) {
      const b = el('button', '', text);
      b.type = 'button';
      b.addEventListener('click', () => {
        document.documentElement.dataset[key] = value;
        for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
        fit();
      });
      row.append(b);
    }
    row.querySelector('button').click(); // the first choice matches the defaults in styles.css
    panel.append(row);
  }
  document.body.append(panel);
