        const depth = near ? rand(0.85, 1) : rand(0.15, 0.75);
        Object.assign(p, {
          x: rand(0, width),
          y: fresh ? rand(0, height) : height + 20,
          image: near ? SOFT : SPECK,
          r: near ? rand(6, 14) : 1.2 + depth * 2.4,
          rise: 2 + depth * 8,
          sway: rand(3, 12),
          wander: rand(8, 18),
          twinkle: rand(3, 8),
          phase: rand(0, TAU),
          alpha: near ? rand(0.04, 0.09) : 0.2 + depth * 0.5,
        });
      },
      draw(p, t, dt) {
