          x: rand(0, width),
          y: rand(0, height),
          r: rand(25, 80),
          vx: rand(-6, 6),
          vy: rand(-5, 3),
          pulse: rand(6, 12),
          phase: rand(0, TAU),
          alpha: rand(0.05, 0.12),
