      settings[key] = value;
      after?.(value);
      refresh();
    };
    addOption('Gold in the air', { Off: 'off', 'Gold dust': 'goldDust', 'Gold leaf': 'goldLeaf', Glints: 'glints' }, settings.air, choose('air', () => populate()));
    addSlider('Amount', 0, 250, 5, settings.amount, (v) => `${v}%`, choose('amount', () => populate(false)));
    if (mouse.matches) addSlider('Mouse glow', 0, 240, 5, settings.glow, (v) => (v ? `${v} px` : 'Off'), choose('glow'));
