        b.style.borderColor = 'rgba(250,250,249,0.25)';
        b.style.color = '#FAFAF9';
      });
      btn.style.borderColor = '#D4AF37';
      btn.style.color = '#D4AF37';
    });
    if (i === 0) {
      btn.style.borderColor = '#D4AF37';
      btn.style.color = '#D4AF37';
    }
    panel.appendChild(btn);
  });

  document.body.appendChild(panel);
})();

