Add-Type -AssemblyName System.Drawing
$vid = 'C:\Users\Waqar Ahmed\Desktop\Claude\Planning\videos\best-yet-frames'
$L = 215; $R = 310; $T = 290; $B = 570
$W = $R - $L + 1; $H = $B - $T + 1

function Get-Rgb([string]$path) {
    $src = New-Object System.Drawing.Bitmap $path
    $bmp = [System.Drawing.Bitmap]::new($src.Width, $src.Height, [System.Drawing.Imaging.PixelFormat]::Format24bppRgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp); $g.DrawImage($src, 0, 0, $src.Width, $src.Height); $g.Dispose(); $src.Dispose()
    $lock = $bmp.LockBits([System.Drawing.Rectangle]::new(0, 0, $bmp.Width, $bmp.Height), [System.Drawing.Imaging.ImageLockMode]::ReadOnly, $bmp.PixelFormat)
    $bytes = New-Object byte[] ($lock.Stride * $bmp.Height)
    [System.Runtime.InteropServices.Marshal]::Copy($lock.Scan0, $bytes, 0, $bytes.Length)
    $stride = $lock.Stride
    $bmp.UnlockBits($lock); $bmp.Dispose()
    [pscustomobject]@{ Bytes = $bytes; Stride = $stride }
}

foreach ($i in 0..30) {
    $name = 'f{0:d3}.png' -f $i
    $p = Join-Path $vid "before-clasp-fix\$name"
    if (-not (Test-Path -LiteralPath $p)) { $p = Join-Path $vid $name }
    $img = Get-Rgb $p
    $bytes = $img.Bytes; $stride = $img.Stride
    $mask = New-Object bool[] ($W * $H)
    for ($y = 0; $y -lt $H; $y++) {
        $row = ($T + $y) * $stride
        for ($x = 0; $x -lt $W; $x++) {
            $k = $row + ($L + $x) * 3
            $rd = [int]$bytes[$k + 2]; $d = $rd - [int]$bytes[$k]
            if ($rd -ge 60 -and $d -ge 30 -and $d * 4 -ge $rd) { $mask[$y * $W + $x] = $true }
        }
    }
    $seen = New-Object bool[] ($W * $H)
    $lines = @()
    for ($s = 0; $s -lt $mask.Length; $s++) {
        if (-not $mask[$s] -or $seen[$s]) { continue }
        $stack = New-Object System.Collections.Generic.Stack[int]
        $stack.Push($s); $seen[$s] = $true
        $n = 0; $x0 = $W; $x1 = -1; $y0 = $H; $y1 = -1; $sr = 0; $sg = 0; $sb = 0
        while ($stack.Count -gt 0) {
            $q = $stack.Pop(); $qx = $q % $W; $qy = ($q - $qx) / $W
            $n++
            if ($qx -lt $x0) { $x0 = $qx }; if ($qx -gt $x1) { $x1 = $qx }; if ($qy -lt $y0) { $y0 = $qy }; if ($qy -gt $y1) { $y1 = $qy }
            $k = ($T + $qy) * $stride + ($L + $qx) * 3
            $sb += $bytes[$k]; $sg += $bytes[$k + 1]; $sr += $bytes[$k + 2]
            for ($dy = -1; $dy -le 1; $dy++) {
                for ($dx = -1; $dx -le 1; $dx++) {
                    $nx = $qx + $dx; $ny = $qy + $dy
                    if ($nx -lt 0 -or $ny -lt 0 -or $nx -ge $W -or $ny -ge $H) { continue }
                    $nq = $ny * $W + $nx
                    if ($mask[$nq] -and -not $seen[$nq]) { $seen[$nq] = $true; $stack.Push($nq) }
                }
            }
        }
        if ($n -ge 4) {
            $lines += "   x $($L + $x0)-$($L + $x1) y $($T + $y0)-$($T + $y1) n=$n h=$($y1 - $y0 + 1) rgb=($([int]($sr / $n)),$([int]($sg / $n)),$([int]($sb / $n)))"
        }
    }
    "$name components: $($lines.Count)"
    $lines
    if ($i -eq 15 -or $i -eq 6) {
        foreach ($yy in 300, 360, 420, 470, 540) {
            $vals = foreach ($xx in (236..276 | Where-Object { $_ % 4 -eq 0 })) { $k = $yy * $stride + $xx * 3; "$xx:$($bytes[$k + 2])/$($bytes[$k + 1])/$($bytes[$k])" }
            "   row $yy  " + ($vals -join ' ')
        }
    }
}

