136	  // Soft, tileable wisps: four octaves of smooth random noise, keeping only the brighter parts.
137	  function hazeTile(size) {
138	    const c = document.createElement('canvas');
139	    c.width = c.height = size;
140	    const g = c.getContext('2d');
141	    const img = g.createImageData(size, size);
142	    const octaves = [4, 8, 16, 32].map((n) => ({ n, v: Float32Array.from({ length: n * n }, Math.random) }));
143	    for (let y = 0; y < size; y++) {
144	      for (let x = 0; x < size; x++) {
145	        let sum = 0;
146	        let amp = 1;
147	        let total = 0;
148	        for (const { n, v } of octaves) {
149	          const fx = (x / size) * n;
150	          const fy = (y / size) * n;
151	          const x0 = Math.floor(fx);
152	          const y0 = Math.floor(fy);
153	          const x1 = (x0 + 1) % n;
154	          const y1 = (y0 + 1) % n;
155	          let tx = fx - x0;
156	          let ty = fy - y0;
157	          tx = tx * tx * (3 - 2 * tx);
158	          ty = ty * ty * (3 - 2 * ty);
159	          const top = v[y0 * n + x0] + (v[y0 * n + x1] - v[y0 * n + x0]) * tx;
160	          const bottom = v[y1 * n + x0] + (v[y1 * n + x1] - v[y1 * n + x0]) * tx;
161	          sum += (top + (bottom - top) * ty) * amp;
162	          total += amp;
163	          amp /= 2;
164	        }
165	        const k = (y * size + x) * 4;
166	        img.data[k] = 222;
167	        img.data[k + 1] = 196;
168	        img.data[k + 2] = 150;
169	        img.data[k + 3] = 255 * Math.max(0, (sum / total - 0.42) / 0.58) ** 1.8;
170	      }
171	    }
172	    g.putImageData(img, 0, 0);
173	    return c;
174	  }
