176	  // An eight-pointed star in each tile, its points joined to the neighbouring stars by thin gold lines.
177	  function buildPattern() {
178	    const size = Math.round(96 * Math.max(unit, 0.75)); // CSS pixels
179	    const px = Math.max(8, Math.round(size * dpr));
180	    const tile = document.createElement('canvas');
181	    tile.width = tile.height = px;
182	    const g = tile.getContext('2d');
183	    g.scale(px / size, px / size);
184	    g.strokeStyle = 'rgba(212,175,55,1)';
185	    g.lineWidth = 1;
186	    const c = size / 2;
187	    const r = size * 0.3;
188	    for (const turn of [0, Math.PI / 4]) {
189	      g.beginPath();
190	      for (let k = 0; k < 4; k++) g.lineTo(c + r * Math.cos(turn + (k * Math.PI) / 2), c + r * Math.sin(turn + (k * Math.PI) / 2));
191	      g.closePath();
192	      g.stroke();
193	    }
194	    g.beginPath();
195	    g.moveTo(0, c);
196	    g.lineTo(c - r, c);
197	    g.moveTo(c + r, c);
198	    g.lineTo(size, c);
199	    g.moveTo(c, 0);
200	    g.lineTo(c, c - r);
201	    g.moveTo(c, c + r);
202	    g.lineTo(c, size);
203	    g.stroke();
204	    starPattern = ctx.createPattern(tile, 'repeat');
205	    starPattern.setTransform(new DOMMatrix([size / px, 0, 0, size / px, 0, 0])); // the tile is in device pixels
206	    lensPattern = lensCtx.createPattern(tile, 'repeat');
207	  }
