214	  // Gold in the air -----------------------------------------------------------------------------------
215	  // Base counts are for a 1440x900 screen at 100%, and scale with the screen's area and each kind's slider.
216	
217	  const KINDS = {
218	    // Fine gold dust on a slow current of air; now and then a speck turns and catches the light.
219	    dust: {
220	      base: 90,
221	      make(p) {
222	        const near = level === 'full' && Math.random() < 0.08;
223	        const depth = near ? rand(0.85, 1) : rand(0.1, 0.8);
224	        Object.assign(p, {
225	          x: rand(0, width),
226	          y: rand(0, height),
227	          near,
228	          depth,
229	          r: near ? rand(4, 8) : 0.9 + depth * 2.2,
230	          vx: 2 + depth * 6,
231	          vy: -(1 + depth * 3),
232	          sway: rand(4, 12),
233	          wander: rand(9, 20),
234	          twinkle: rand(3, 8),
235	          catches: !near && Math.random() < 0.35,
236	          catchEvery: rand(7, 16),
237	          phase: rand(0, TAU),
238	          alpha: near ? rand(0.05, 0.1) : 0.25 + depth * 0.5,
239	        });
240	      },
241	      draw(p, t, dt) {
242	        p.x = wrap(p.x + p.vx * unit * dt, width);
243	        p.y = wrap(p.y + p.vy * unit * dt, height);
244	        const x = p.x + wave(t, p.wander, p.phase) * p.sway * unit;
245	        const y = p.y + wave(t, p.wander * 1.3, p.phase) * p.sway * 0.5 * unit;
246	        const r = p.r * Math.max(unit, 0.8);
247	        stamp(p.near ? S.soft : S.speck, x, y, r, p.alpha * (0.75 + 0.25 * wave(t, p.twinkle, p.phase)));
248	        if (!p.catches) return;
249	        const shine = Math.max(0, wave(t, p.catchEvery, p.phase)) ** 30; // a slow swell, a few times a minute
250	        if (shine > 0.02) stamp(S.glint, x, y, (5 + 5 * p.depth) * unit * (0.5 + 0.5 * shine), shine * 0.9);
251	      },
252	    },
253	
254	    // Flakes of gold leaf falling slowly, turning over as they fall and flashing as they face the light.
255	    leaf: {
256	      base: 16,
257	      make(p, fresh) {
258	        const depth = rand(0.3, 1);
259	        Object.assign(p, {
260	          x: rand(0, width),
261	          y: fresh ? rand(0, height) : -20,
262	          leaf: Math.floor(rand(0, LEAF_SHAPES.length)),
263	          size: 5 + depth * 7,
264	          fall: 5 + depth * 9,
265	          sway: rand(15, 35),
266	          wander: rand(5, 9),
267	          angle: rand(0, TAU),
268	          spin: rand(-0.5, 0.5),
269	          flip: rand(0.8, 1.6),
270	          phase: rand(0, TAU),
271	          alpha: 0.5 + depth * 0.45,
272	        });
273	      },
274	      draw(p, t, dt) {
275	        p.y += p.fall * unit * dt;
276	        if (p.y > height + 20) this.make(p, false);
277	        p.angle += p.spin * dt;
278	        const x = p.x + wave(t, p.wander, p.phase) * p.sway * unit;
279	        const face = Math.cos(t * p.flip + p.phase); // 1 or -1 facing the viewer, 0 edge-on
280	        const s = p.size * unit;
281	        const cos = Math.cos(p.angle) * dpr;
282	        const sin = Math.sin(p.angle) * dpr;
283	        ctx.globalAlpha = p.alpha * presence * (0.35 + 0.65 * Math.abs(face));
284	        ctx.setTransform(cos, sin, -sin * face, cos * face, x * dpr, p.y * dpr);
285	        ctx.drawImage(S.leaves[p.leaf], -s / 2, -s / 2, s, s);
286	        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
287	        const shine = Math.max(0, face) ** 24;
288	        if (shine > 0.02) stamp(S.glint, x, p.y, s * 1.2, shine * 0.75);
289	      },
290	    },
291	
292	    // Sparkles that catch the light for a moment, then appear somewhere else.
293	    glints: {
294	      base: 24,
295	      make(p) {
296	        Object.assign(p, { r: rand(6, 13), period: rand(4, 10), offset: rand(0, 1), alpha: rand(0.55, 0.95), cycle: null });
297	      },
298	      draw(p, t) {
299	        const c = t / p.period + p.offset;
300	        const cycle = Math.floor(c);
301	        if (cycle !== p.cycle) {
302	          p.cycle = cycle;
303	          p.x = rand(0, width);
304	          p.y = rand(0, height);
305	        }
306	        const flash = Math.sin((c - cycle) * Math.PI) ** 24;
307	        if (flash > 0.01) stamp(S.glint, p.x, p.y, p.r * unit * (0.5 + 0.5 * flash), p.alpha * flash);
308	      },
309	    },
310	  };
