312	  // Makes the right number of one kind. A fresh start replaces them all; otherwise some are added or removed, so
313	  // dragging a slider doesn't restart the ones already there.
314	  function populate(kind, fresh = true) {
315	    const area = Math.min(1.5, Math.max(0.35, (width * height) / (1440 * 900)));
316	    let n = Math.round((KINDS[kind].base * area * settings[kind]) / 100);
317	    if (level === 'lite') n = Math.ceil(n / 2);
318	    n = Math.min(n, MAX_PARTICLES);
319	    const list = particles[kind];
320	    if (fresh) list.length = 0;
321	    list.length = Math.min(list.length, n);
322	    while (list.length < n) {
323	      const p = {};
324	      KINDS[kind].make(p, true);
325	      list.push(p);
326	    }
327	  }
