331	  // A warm light behind the book. Its middle is erased with the book, so it shows as a glow around the edges.
332	  function drawHalo(t) {
333	    const b = hero.book;
334	    if (!settings.halo || !b) return false;
335	    const r = Math.max(b.right - b.left, b.bottom - b.top) * (0.95 + 0.04 * wave(t, 11));
336	    ctx.globalAlpha = (settings.halo / 100) * presence;
337	    ctx.drawImage(S.halo, (b.left + b.right) / 2 - r, (b.top + b.bottom) / 2 - r, r * 2, r * 2);
