341	  // Two layers of haze drifting slowly in different directions. Left out at lite quality.
342	  const HAZE_LAYERS = [
343	    { scale: 6, vx: 5, vy: -1.5, alpha: 0.6 },
344	    { scale: 10, vx: -3, vy: -0.8, alpha: 0.4 },
345	  ];
