372	  // Moves the lamp after the mouse with a slight lag, fading in and out. Returns whether it is showing.
373	  function trackLamp(dt) {
374	    const on = (settings.glow > 0 || settings.pattern === 'mouse') && pointer.inside && mouse.matches;
375	    if (settings.glow > 0) lamp.r = settings.glow;
376	    const snap = lamp.strength < 0.02; // appears where the mouse is, rather than sliding in from a corner
377	    lamp.strength = ease(lamp.strength, on ? 1 : 0, 0.35, dt);
378	    if (lamp.strength < 0.005) return false;
379	    const rect = canvas.getBoundingClientRect();
380	    const x = pointer.x - rect.left;
381	    const y = pointer.y - rect.top;
382	    lamp.x = snap ? x : ease(lamp.x, x, 0.08, dt);
383	    lamp.y = snap ? y : ease(lamp.y, y, 0.08, dt);
384	    return true;
385	  }
