394	  // The pattern, uncovered in a soft circle under the mouse. It stays fixed to the page as the circle moves over it.
395	  function drawLens() {
396	    if (settings.pattern !== 'mouse') return false;
397	    const size = Math.round(LENS * 2 * dpr);
