399	    lensCtx.globalCompositeOperation = 'source-over';
400	    lensCtx.clearRect(0, 0, size, size);
401	    lensPattern.setTransform(new DOMMatrix([1, 0, 0, 1, -(lamp.x - LENS) * dpr, -(lamp.y - LENS) * dpr]));
