403	    lensCtx.fillRect(0, 0, size, size);
404	    lensCtx.globalCompositeOperation = 'destination-in';
405	    lensCtx.drawImage(S.fade, 0, 0, size, size);
406	    ctx.globalAlpha = 0.45 * lamp.strength;
