411	  // Erases this layer over the book, with a soft edge, so nothing ever sits on the Qur'an.
412	  function eraseBook() {
413	    const b = hero.book;
414	    if (!b) return;
415	    const s = b.scale;
416	    const f = CLEAR.feather * s;
417	    const l = b.left - CLEAR.side * s;
418	    const r = b.right + CLEAR.side * s;
419	    const t = b.top - CLEAR.top * s;
420	    const bottom = b.bottom + CLEAR.bottom * s;
421	    const w = r - l;
422	    const h = bottom - t;
423	    ctx.globalCompositeOperation = 'destination-out';
424	    ctx.globalAlpha = 1;
425	    ctx.fillStyle = '#000';
426	    ctx.fillRect(l, t, w, h);
427	    ctx.drawImage(MASK, 64, 0, 1, 64, l, t - f, w, f);     // top edge
428	    ctx.drawImage(MASK, 64, 64, 1, 64, l, bottom, w, f);   // bottom edge
429	    ctx.drawImage(MASK, 0, 64, 64, 1, l - f, t, f, h);     // left edge
430	    ctx.drawImage(MASK, 64, 64, 64, 1, r, t, f, h);        // right edge
431	    ctx.drawImage(MASK, 0, 0, 64, 64, l - f, t - f, f, f); // corners
432	    ctx.drawImage(MASK, 64, 0, 64, 64, r, t - f, f, f);
433	    ctx.drawImage(MASK, 0, 64, 64, 64, l - f, bottom, f, f);
434	    ctx.drawImage(MASK, 64, 64, 64, 64, r, bottom, f, f);
435	    ctx.globalCompositeOperation = 'source-over';
436	  }
