438	  // For erasing the book's area: opaque at the centre, clear 64 px out. Drawn in slices, so the fade is the
439	  // same width all round a rectangle of any size.
440	  const MASK = sprite(128, (g, size) => {
441	    const img = g.createImageData(size, size);
442	    for (let y = 0; y < size; y++) {
443	      for (let x = 0; x < size; x++) {
444	        const d = Math.min(1, Math.hypot(x + 0.5 - 64, y + 0.5 - 64) / 64);
445	        img.data[(y * size + x) * 4 + 3] = 255 * (1 - d * d * (3 - 2 * d));
446	      }
447	    }
448	    g.putImageData(img, 0, 0);
449	  });
