451	  function paint(t, dt) {
452	    if (inked) ctx.clearRect(0, 0, width, height);
453	    presence = ease(presence, 1, 0.8, dt);
454	    const lit = trackLamp(dt);
455	    let drew = drawHalo(t);
456	    drew = drawHaze(t) || drew;
457	    drew = drawPattern() || drew;
458	    for (const kind in KINDS) {
459	      if (!particles[kind].length) continue;
460	      for (const p of particles[kind]) KINDS[kind].draw(p, t, dt);
461	      drew = true;
462	    }
463	    if (lit) {
464	      drew = drawLens() || drew;
465	      drew = drawGlow() || drew;
466	    }
467	    ctx.globalAlpha = 1;
468	    if (drew) eraseBook();
469	    inked = drew;
470	  }
