472	  // The book ---------------------------------------------------------------------------------------------
473	
474	  // Sine waves whose periods never line up, so the movement doesn't visibly repeat. k is the strength.
475	  const IDLE = {
476	    float: (t, k) => `translate3d(${wave(t, 11) * 1.5 * k * unit}px, ${wave(t, 6.5) * 4 * k * unit}px, 0)`,
477	    breathe: (t, k) => `scale(${1 + (wave(t, 7) + 1) * 0.005 * k})`,
478	    drift: (t, k) =>
479	      `rotateX(${wave(t, 9) * 0.6 * k}deg) rotateY(${wave(t, 13, 1) * k}deg) translate3d(0, ${wave(t, 7) * 2 * k * unit}px, 0)`,
480	  };
