482	  function moveBook(t) {
483	    const k = (idle * settings.move) / 100;
484	    // A hair of rotation stops the browser snapping the book to whole pixels, which made Float and Breathe
485	    // move in visible steps.
486	    const hair = (0.1 + wave(t, 17, 2) * 0.06) * Math.min(k, 1);
487	    setBook(k > 0.01 ? `perspective(1600px) rotate(${hair}deg) ${IDLE[motion](t, k)}` : '');
488	  }
