490	  function setBook(transform) {
491	    if (transform === bookTransform) return;
492	    bookTransform = transform;
493	    subject.style.transform = transform;
494	    // A layer of its own only while moving: during the opening it would add a pass for the aayat's blend every frame.
495	    subject.style.willChange = transform ? 'transform' : '';
496	  }
