500	  function resize() {
501	    width = canvas.clientWidth;
502	    height = canvas.clientHeight;
503	    unit = height / 900;
504	    dpr = Math.min(devicePixelRatio || 1, level === 'full' ? 1.5 : 1); // soft light doesn't need full retina sharpness
505	    canvas.width = Math.round(width * dpr);
506	    canvas.height = Math.round(height * dpr);
507	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
508	    inked = false; // resizing clears the canvas
509	    buildPattern();
510	    for (const kind in KINDS) populate(kind);
