514	  function running() {
515	    const air = settings.dust || settings.leaf || settings.glints || settings.haze || settings.halo || settings.pattern === 'faint';
516	    const book = settings.idle !== 'off' && settings.move > 0;
517	    const pointed = (settings.glow > 0 || settings.pattern === 'mouse') && mouse.matches;
518	    return visible && !reduceMotion.matches && level !== 'off' && Boolean(air || book || pointed);
519	  }
520	
521	  // Starts the loop if there is anything to animate; otherwise leaves the book still and the canvas clear.
522	  function refresh() {
523	    if (running()) return wake();
524	    idle = 0;
525	    setBook('');
526	    if (inked) ctx.clearRect(0, 0, width, height);
527	    inked = false;
528	  }
529	
530	  function wake() {
531	    if (raf) return;
532	    last = windowStart = frames = 0;
533	    raf = requestAnimationFrame(frame);
534	  }
535	
536	  function measure(now, dtMs) {
537	    if (gliding || now - lastMove < 1000 || now < WARMUP || document.hidden || dtMs > 250) {
538	      windowStart = 0; // not a fair moment to judge; a fresh window starts later
539	      return;
540	    }
541	    if (!windowStart) {
542	      windowStart = now;
543	      frames = 0;
544	      return;
545	    }
546	    frames++;
547	    if (now - windowStart < WINDOW) return;
548	    badWindows = (frames * 1000) / (now - windowStart) < MIN_FPS ? badWindows + 1 : 0;
549	    windowStart = 0;
550	    if (badWindows < BAD_WINDOWS) return;
551	    badWindows = 0;
552	    level = level === 'full' ? 'lite' : 'off';
553	    resize();
554	    refresh();
555	  }
556	
557	  // Uses elapsed time, so it moves at the same speed on 60 Hz and 144 Hz screens.
558	  function frame(now) {
559	    raf = 0;
560	    if (!running()) return refresh();
561	    const dtMs = last ? now - last : 1000 / 60;
562	    const dt = Math.min(dtMs, 50) / 1000;
563	    last = now;
564	    const t = now / 1000;
565	    const quiet = !gliding && now - lastMove > IDLE_DELAY;
566	    idle = ease(idle, quiet && settings.idle !== 'off' ? 1 : 0, quiet ? 1.2 : 0.12, dt);
567	    moveBook(t);
568	    paint(t, dt);
569	    measure(now, dtMs);
570	    if (!raf && running()) raf = requestAnimationFrame(frame);
571	  }
572	
573	  const moved = () => (lastMove = performance.now());
574	  addEventListener('scroll', moved, { passive: true });
575	  hero.addEventListener('bookmove', () => (gliding = true));
576	  hero.addEventListener('bookrest', () => {
577	    gliding = false;
578	    moved();
579	  });
580	  addEventListener(
581	    'pointermove',
582	    (e) => {
583	      if (e.pointerType !== 'mouse') return;
584	      pointer.x = e.clientX;
585	      pointer.y = e.clientY;
586	      pointer.inside = true;
587	    },
588	    { passive: true },
589	  );
590	  root.addEventListener('mouseleave', () => (pointer.inside = false));
591	  reduceMotion.addEventListener('change', refresh);
592	  new ResizeObserver(resize).observe(canvas);
593	  new IntersectionObserver(([entry]) => {
594	    visible = entry.isIntersecting;
595	    refresh();
596	  }).observe(hero);
597	
598	  // TRYOUT ------------------------------------------------------------------------------------------------
599	  // Phase 4 options, added to main.js's panel on this PC or a phone on the same wifi. Once the user picks: put
600	  // the picks in `settings`, delete what was switched off, then delete this block and the .readout CSS.
601	
602	  if (window.addOption) {
603	    const choose = (key, after) => (value) => {
604	      settings[key] = value;
605	      if (level !== 'full') {
606	        level = 'full';
607	        badWindows = 0;
608	        resize();
609	      }
610	      after?.(value);
611	      refresh();
612	    };
613	    const percent = (v) => (v ? `${v}%` : 'Off');
614	    for (const [kind, label] of [['dust', 'Gold dust'], ['leaf', 'Gold leaf'], ['glints', 'Glints']]) {
615	      addSlider(label, 0, 250, 5, settings[kind], percent, choose(kind, () => populate(kind, false)));
616	    }
617	    addSlider('Haze', 0, 100, 5, settings.haze, percent, choose('haze'));
618	    addSlider('Light behind book', 0, 100, 5, settings.halo, percent, choose('halo'));
619	    const patterns = mouse.matches ? { Off: 'off', Faint: 'faint', 'Under the mouse': 'mouse' } : { Off: 'off', Faint: 'faint' };
620	    addOption('Gold pattern', patterns, settings.pattern, choose('pattern'));
621	    if (mouse.matches) addSlider('Mouse glow', 0, 240, 5, settings.glow, (v) => (v ? `${v} px` : 'Off'), choose('glow'));
622	    addOption('Book when still', { Off: 'off', Float: 'float', Breathe: 'breathe', Drift: 'drift' }, settings.idle, choose('idle', (v) => v !== 'off' && (motion = v)));
623	    addSlider('Movement', 0, 300, 5, settings.move, (v) => `${v}%`, choose('move'));
624	
625	    // How smoothly this device runs: frames a second while scrolling and while still, counted separately.
626	    const readout = document.createElement('p');
627	    readout.className = 'readout';
628	    document.querySelector('.tryout').append(readout);
629	    const scrolling = { frames: 0, ms: 0, fps: null };
630	    const resting = { frames: 0, ms: 0, fps: null };
631	    let prev = 0;
632	    let since = 0;
633	    const meter = (now) => {
634	      const dt = prev ? now - prev : 0;
635	      prev = now;
636	      if (dt > 0 && dt < 250) {
637	        const bucket = gliding || now - lastMove < 300 ? scrolling : resting;
638	        bucket.frames++;
639	        bucket.ms += dt;
640	      }
641	      if (now - since > 1000) {
642	        since = now;
643	        for (const b of [scrolling, resting]) {
644	          if (b.ms > 300) b.fps = Math.round((b.frames * 1000) / b.ms);
645	          b.frames = b.ms = 0;
646	        }
647	        const show = (b) => b.fps ?? '–';
648	        const note = {
649	          full: '',
650	          lite: ' Effects were lightened because this device was slow while the book was still.',
651	          off: ' Effects were switched off because this device was slow while the book was still. Choose any effect option to turn them back on.',
652	        }[level];
653	        readout.textContent = `Smoothness on this device (60 is smooth): scrolling ${show(scrolling)}, still ${show(resting)} frames a second.${note}`;
654	      }
655	      requestAnimationFrame(meter);
656	    };
657	    requestAnimationFrame(meter);
658	  }
659	})();
