$fmt = [System.Drawing.Imaging.PixelFormat]::Format24bppRgb
$rules = @{ 6 = 268; 7 = 267; 8 = 267; 9 = 267; 10 = 268; 11 = 269; 12 = 271; 13 = 274; 14 = 278; 15 = 283; 16 = 288; 17 = 296; 18 = 304; 19 = 314 }
$Y0 = 150; $Y1 = 620

function Read-Frame([string]$path) {
    $src = New-Object System.Drawing.Bitmap $path
    $bmp = [System.Drawing.Bitmap]::new($src.Width, $src.Height, $fmt)
    $g = [System.Drawing.Graphics]::FromImage($bmp); $g.DrawImage($src, 0, 0, $src.Width, $src.Height); $g.Dispose(); $src.Dispose()
    $lock = $bmp.LockBits([System.Drawing.Rectangle]::new(0, 0, $bmp.Width, $bmp.Height), [System.Drawing.Imaging.ImageLockMode]::ReadOnly, $fmt)
    $bytes = New-Object byte[] ($lock.Stride * $bmp.Height)
    [System.Runtime.InteropServices.Marshal]::Copy($lock.Scan0, $bytes, 0, $bytes.Length)
    $f = [pscustomobject]@{ Bytes = $bytes; Stride = $lock.Stride }
    $bmp.UnlockBits($lock)
    return [pscustomobject]@{ F = $f; Bmp = $bmp }
}

$ids = 6..19
$cw = 136; $ch = ($Y1 - $Y0) * 2
$sheet = [System.Drawing.Bitmap]::new($ids.Count * $cw, $ch)
$g = [System.Drawing.Graphics]::FromImage($sheet)
$g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor
$g.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::Half
$font = [System.Drawing.Font]::new('Consolas', [single]9)

for ($j = 0; $j -lt $ids.Count; $j++) {
    $i = $ids[$j]; $rule = $rules[$i]
    $name = 'f{0:d3}.png' -f $i
    $p = Join-Path $vid "before-clasp-fix\$name"
    if (-not (Test-Path -LiteralPath $p)) { $p = Join-Path $vid $name }
    $r = Read-Frame $p
    $bytes = $r.F.Bytes; $s = $r.F.Stride

    # Deviation from each column's median over the rows, in a band left of the rule.
    $xs = ($rule - 46)..($rule - 19)
    $rows = $Y1 - $Y0 + 1
    $med = @{}
    foreach ($x in $xs) {
        foreach ($c in 0, 1, 2) {
            $vals = New-Object int[] $rows
            for ($y = $Y0; $y -le $Y1; $y++) { $vals[$y - $Y0] = $bytes[$y * $s + $x * 3 + $c] }
            [Array]::Sort($vals)
            $med["$x,$c"] = $vals[[int]($rows / 2)]
        }
    }
    $flag = New-Object int[] $rows
    $xmin = 9999; $xmax = -1
    for ($y = $Y0; $y -le $Y1; $y++) {
        $n = 0
        foreach ($x in $xs) {
            $k = $y * $s + $x * 3
            $d = [math]::Abs($bytes[$k] - $med["$x,0"]) + [math]::Abs($bytes[$k + 1] - $med["$x,1"]) + [math]::Abs($bytes[$k + 2] - $med["$x,2"])
            if ($d -gt 30) { $n++; if ($x -lt $xmin) { $xmin = $x }; if ($x -gt $xmax) { $xmax = $x } }
        }
        $flag[$y - $Y0] = $n
    }
    $runs = @(); $start = -1; $peak = 0; $gap = 0
    for ($y = 0; $y -lt $rows; $y++) {
        if ($flag[$y] -ge 2) {
            if ($start -lt 0) { $start = $y; $peak = 0 }
            $gap = 0; $end = $y
            if ($flag[$y] -gt $peak) { $peak = $flag[$y] }
        } elseif ($start -ge 0) {
            $gap++
            if ($gap -gt 4) { $runs += "y $($Y0 + $start)-$($Y0 + $end) (peak $peak)"; $start = -1 }
        }
    }
    if ($start -ge 0) { $runs += "y $($Y0 + $start)-$($Y0 + $end) (peak $peak)" }
    $xinfo = if ($xmax -ge 0) { "x $($xmin - $rule) to $($xmax - $rule) from rule" } else { '' }
    "$name rule $rule  $xinfo  runs: $($runs -join ', ')"

    $src = [System.Drawing.Rectangle]::new($rule - 64, $Y0, 68, $Y1 - $Y0)
    $g.DrawImage($r.Bmp, [System.Drawing.Rectangle]::new($j * $cw, 0, $cw, $ch), $src, [System.Drawing.GraphicsUnit]::Pixel)
    $g.DrawString($name.Substring(0, 4), $font, [System.Drawing.Brushes]::White, [single]($j * $cw + 3), [single]3)
    $r.Bmp.Dispose()
}
$g.Dispose(); $sheet.Save($out, [System.Drawing.Imaging.ImageFormat]::Png); $sheet.Dispose()
"saved $out : frames f006-f019 before, 2x, frame x rule-64..rule+3, y $Y0-$Y1 (sheet y = (frame y - $Y0) * 2)"

