    $xinfo = if ($xmax -ge 0) { "x $($xmin - $rule) to $($xmax - $rule) from rule" } else { '' }
    "$name rule $rule  $xinfo  runs: $($runs -join ', ')"

    $src = [System.Drawing.Rectangle]::new($rule - 64, $Y0, 68, $Y1 - $Y0)
    $g.DrawImage($r.Bmp, [System.Drawing.Rectangle]::new($j * $cw, 0, $cw, $ch), $src, [System.Drawing.GraphicsUnit]::Pixel)
    $g.DrawString($name.Substring(0, 4), $font, [System.Drawing.Brushes]::White, [single]($j * $cw + 3), [single]3)
    $r.Bmp.Dispose()
}
$g.Dispose(); $sheet.Save($out, [System.Drawing.Imaging.ImageFormat]::Png); $sheet.Dispose()
"saved $out : frames f006-f019 before, 2x, frame x rule-64..rule+3, y $Y0-$Y1 (sheet y = (frame y - $Y0) * 2)"

