function Find-Clasps($f, [int]$rule) {
    $x0 = $rule - $Far
    $W = $Far - $Near + 1
    $H = $Bottom - $Top + 1

    # Each column's usual colour: its median down the book, which the clasps are too small to shift.
    $rows = $MedianBottom - $MedianTop + 1
    $usual = New-Object int[] ($W * 3)
    $vals = New-Object int[] $rows
    for ($x = 0; $x -lt $W; $x++) {
        for ($c = 0; $c -lt 3; $c++) {
            for ($y = 0; $y -lt $rows; $y++) { $vals[$y] = $f.Bytes[($MedianTop + $y) * $f.Stride + ($x0 + $x) * 3 + $c] }
