            $usual[$x * 3 + $c] = $vals[[int][math]::Floor($rows / 2)]
        }
    }

    $odd = New-Object bool[] ($W * $H)
    $cells = New-Object System.Collections.Generic.List[int]
    for ($y = 0; $y -lt $H; $y++) {
        $row = ($Top + $y) * $f.Stride
        for ($x = 0; $x -lt $W; $x++) {
            $k = $row + ($x0 + $x) * 3
            $d = [math]::Abs([int]$f.Bytes[$k] - $usual[$x * 3]) + [math]::Abs([int]$f.Bytes[$k + 1] - $usual[$x * 3 + 1]) + [math]::Abs([int]$f.Bytes[$k + 2] - $usual[$x * 3 + 2])
            if ($d -gt $Deviation) {
                $odd[$y * $W + $x] = $true
                $cells.Add($y * $W + $x)
            }
        }
    }

    # Odd pixels within 3 px of each other belong to the same clasp.
    $seen = New-Object bool[] ($W * $H)
    $boxes = New-Object System.Collections.Generic.List[object]
    foreach ($s in $cells) {
        if ($seen[$s]) { continue }
        $stack = New-Object System.Collections.Generic.Stack[int]
        $stack.Push($s); $seen[$s] = $true
        $n = 0; $bx0 = $W; $bx1 = -1; $by0 = $H; $by1 = -1
