313	    left: calc(var(--x0, 0px) + 262px * var(--s, 1));
314	    right: auto;
315	    top: calc(var(--y0, 0px) + 80px * var(--s, 1));
316	    width: calc(375px * var(--s, 1));
317	    height: calc(560px * var(--s, 1));
318	    padding: calc(56px * var(--s, 1)) calc(16px * var(--s, 1));
319	    font-size: max(9px, calc(16px * var(--s, 1)));
320	    color: #2B211B;
